from lib import *
S = SS('f66')
R = J('f66'); df = R['defaults']
steps = [
    step(f"没有任何配置时:app.config 有 {df[0]} 个默认键,DEBUG = False、SECRET_KEY = None,自己的键 PAGE_SIZE 不存在。这是所有后续加载的起点。", t=tl(S(1)), done=lidx(S(1), '默认键数'), kv=KV([['默认键数', str(df[0])], ['DEBUG', 'False'], ['SECRET_KEY', 'None']], ['SECRET_KEY'])),
    step("后加载的覆盖先加载的(同一个 app 依次执行,观察 PAGE_SIZE 与 ENV_NAME):from_object('defaults_cfg') → 10 / from-defaults-file;from_pyfile('prod.py') → 50 / from-prod-file;from_file('cfg.json', load=json.load) → 7 / from-json;from_prefixed_env()(FLASK_PAGE_SIZE=200、FLASK_ENV_NAME=\"from-env\")→ 200 / from-env;config.update(PAGE_SIZE=1) → 1;config['PAGE_SIZE'] = 2 → 2。没有「优先级表」,就是代码执行的先后顺序,最后一次写入的赢。", t=tl(S(2)), done=lidx(S(2), '(开始)', 'from_object("defaults_cfg")', 'from_pyfile("prod.py")', 'from_file("cfg.json"'), mark=lidx(S(2), 'from_prefixed_env()', 'config.update', 'config["PAGE_SIZE"] = 2'), kv=KV([['10 → 50 → 7 → 200 → 1 → 2', 'object → pyfile → file → prefixed_env → update → 赋值'], ['规则', '最后写入的赢']], ['规则'])),
    step("只有大写的键会被加载:defaults_cfg.py 里的 lower_case = \"ignored\" 没有进入 config(lower_case in config 为 False),大写的 ENV_NAME、FEATURES、PAGE_SIZE 都进来了。from_object、from_pyfile、from_file 都有这个规则。", t=tl(S(3)), done=lidx(S(3), 'lower_case'), kv=KV([['大写键', '加载'], ['小写键', '忽略']], ['小写键'])),
    step("instance 目录:Flask(…, instance_relative_config=True) 时 config.root_path 变成 instance_path(<项目>/instance),from_pyfile('local.py') 读的是 instance/local.py,得到 PAGE_SIZE = 99、SECRET_KEY = instance-secret;不开这个选项时 config.root_path 是应用的 root_path。instance 目录适合放不进版本库的本地配置。", t=tl(S(4)), done=lidx(S(4), 'instance_path =', 'from_pyfile("local.py")'), mark=lidx(S(4), '不开 instance_relative_config'), kv=KV([['instance_relative_config=True', 'config.root_path = instance 目录'], ['默认', 'config.root_path = 应用目录']], ['instance_relative_config=True'])),
    step("from_prefixed_env 的类型转换:值先按 JSON 解析,失败就保持字符串。FLASK_N=5 → int 5;FLASK_F=1.5 → float;FLASK_B1=true → True;FLASK_B2=false → False;FLASK_NONE=null → None;FLASK_LIST=[1, 2, 3] → 列表;FLASK_TXT=hello → 字符串 'hello';FLASK_QUOTED=\"hello\" → 'hello'(JSON 字符串去掉引号);FLASK_EMPTY= → 空字符串;双下划线嵌套:FLASK_DB__HOST、FLASK_DB__PORT → DB = {'HOST': 'localhost', 'PORT': 5432};不带 FLASK_ 前缀的 OTHER_X 不会被加载;from_prefixed_env('MYAPP') 可以换前缀。", t=tl(S(5)), done=lidx(S(5), 'FLASK_N ', 'FLASK_F ', 'FLASK_B1', 'FLASK_B2'), mark=lidx(S(5), 'FLASK_NONE', 'FLASK_LIST', 'FLASK_DB', '自定义前缀'), kv=KV([['数字 / 布尔 / null / 列表', 'JSON 解析成对应类型'], ['不是合法 JSON', '保持字符串'], ['A__B', '嵌套字典']], ['不是合法 JSON'])),
    step("get_namespace 按前缀取出一组配置:get_namespace('SMTP_') 得到 {'host': 'h', 'port': 25, 'use_tls': True}(键去掉前缀并转成小写,方便直接 **kwargs 传给别的函数);lowercase=False 时保留大写 {'HOST': …}。", t=tl(S(6)), done=lidx(S(6), 'get_namespace("SMTP_") →', 'lowercase=False'), kv=KV([['get_namespace', "{'host': …, 'port': …, 'use_tls': …}"]], ['get_namespace'])),
]
